/**
 * Trunk resolution for the stacked-PR guards.
 *
 * A literal ['main', 'master', 'develop'] list is a guess, and it is wrong in
 * two ordinary repos: one whose trunk is `develop` while `main` survives as a
 * release branch, and one whose trunk is `dev`. Both were shipping wrong
 * advice, so `git symbolic-ref refs/remotes/origin/HEAD` is asked first. That
 * ref is what `git remote set-head origin -a` writes and what `gh` itself
 * treats as the default branch.
 *
 * Returns null when the symref is unset rather than substituting a name, so a
 * caller can print "origin/HEAD is unset" instead of asserting a trunk it does
 * not know. The symref is local state and can be stale; a caller that must be
 * right about the remote's current default should pass it explicitly.
 *
 * SECURITY: every invocation uses execFileSync with an ARGUMENT ARRAY and no
 * shell, matching the rule in worktree-merge-verifier.ts. Branch names are
 * attacker-influenced (git accepts `evil;id`), so no value from this module
 * may ever reach a template literal that is handed to a shell.
 */

import { execFileSync } from 'node:child_process';

/**
 * The repository's trunk branch, bare (`develop`, not `origin/develop`).
 * Null when `origin/HEAD` is unset or git fails.
 */
export function resolveTrunkBranch(projectDir: string): string | null {
  try {
    const out = execFileSync('git', ['symbolic-ref', '--short', 'refs/remotes/origin/HEAD'], {
      cwd: projectDir,
      encoding: 'utf8',
      timeout: 3000,
      stdio: ['ignore', 'pipe', 'ignore'],
    });
    const ref = String(out ?? '').trim();
    if (!ref) return null;
    const branch = ref.replace(/^origin\//, '');
    return branch || null;
  } catch {
    return null;
  }
}

/**
 * Branches tried only when `origin/HEAD` is unset. Ordered by how often each
 * is a trunk, not by preference: the symref outranks all of them.
 */
export const TRUNK_FALLBACKS = ['main', 'master', 'develop', 'dev'] as const;
